  $('#palList').innerHTML = palItems.length ? palItems.map((it, i) => `<li data-i="${i}" class="${i === 0 ? 'on' : ''}"><span class="pk">${it.kind}</span><div>${it.html}</div></li>`).join('') : '<li class="muted">Nothing found.</li>';
