  const el = editor.children[at]; if (!el) return;
  el.scrollIntoView({ block: 'center' }); el.classList.remove('hm-flash'); void el.offsetWidth; el.classList.add('hm-flash');
  setTimeout(() => el.classList.remove('hm-flash'), 2000);
