    if (p.e.b !== null) { const x2 = X(p.e.b); s += `<rect x="${x}" y="${axisY - 4}" width="${Math.max(3, x2 - x)}" height="8" rx="4" fill="${SERIES[0]}" fill-opacity=".55"/>`; }
