const srcShort = s => { if (!s) return 'Unknown source'; const l = sourceLabel(s); return l.who ? l.who + (l.yr ? ' ' + l.yr : '') : (l.title.length > 40 ? l.title.slice(0, 38) + '…' : l.title); };
