  if (c.dates === 'us') add('dates', 'Dates as “Month D, YYYY”', new RegExp(`\\b(\\d{1,2}) (${HS_MONTHS}) (\\d{4})\\b`, 'g'), mt => `${mt[2]} ${mt[1]}, ${mt[3]}`);
