const LOC_ABBR = { page: 'p.', chapter: 'ch.', section: 'sec.', paragraph: 'para.', line: 'l.', figure: 'fig.', table: 'table', volume: 'vol.', part: 'pt.', note: 'n.', column: 'col.', folio: 'fol.', verse: 'v.', book: 'bk.', timestamp: 'at' };
