  const low = text.toLowerCase();
  const ent = (P.entities || []).map(e => [e.name, ...(e.variants || [])]).flat().filter(n => n && n.length > 2).sort((a, b) => b.length - a.length).find(n => new RegExp('\\b' + n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i').test(text));
