  disp: '--cl-bg:linear-gradient(var(--cs) 0 1.5px,transparent 1.5px 3.5px,var(--cs) 3.5px 5px);--cl-h:5px',
  cut: '--cl-bg:linear-gradient(var(--cs),var(--cs));--cl-pos:0 58%;--cl-h:1.5px',
