    incoming.forEach(x => { const l = lm.get(x.id); if (l) out.push(merge3(l, x, pm.get(x.id))); else if (!pm.has(x.id)) out.push(x); });
    local.forEach(x => { if (!im.has(x.id) && !pm.has(x.id)) out.push(x); });
